insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 1, 'The EGINA Base scenario reports an internal rate of return of 29.5998 percent with the status ok. Where does that number come from?', '["It is the screening threshold the studio applies to an FPSO concept, carried on the concept beside its three capex fields of 520.0000, 1350.0000 and 380.0000.", "It is the discount rate the net present value of 2047.5653 million USD was struck at, which the studio raises above its default of 10.0000 percent for a long shape.", "It is solved: the discount rate that drives this flow''s net present value to zero, fixed by the capex of 2250.0000 million USD, the shape, the price and the terms.", "It is a score the engine formed about the concept, weighing the money returned against the 2250.0000 million USD committed."]'::jsonb, 2, 'Nobody chose 29.5998. Year 0 spends 2250.0000 and the years after it earn, and the rate falls out of that flow; the value of 2047.5653 was taken at 10.0000 percent.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 2, 'At 40.0000 USD a barrel the same concept reports a rate of 8.2444 percent and a net present value of -161.0098 million USD. How are both true at once?', '["The flow turns positive, so a root exists at 8.2444 percent, and the value was struck at a discount rate of 10.0000 percent, which is more than this flow earns.", "The rate is solved before royalty at 12.5000 percent and tax at 30.0000 percent while the value is struck after them, so the two are reading one flow at different points.", "The search failed at that price and returned a floor, so -161.0098 million USD is the real finding and 8.2444 percent is only where the solver gave up.", "A rate under the discount rate is recorded by convention rather than solved, as the published zero production case records 0 beside its value of -979.6325."]'::jsonb, 0, 'A positive rate is not a profitable one. 8.2444 is below the 10.0000 percent the money is charged at, and the -161.0098 is that comparison already made.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 3, 'The Base cumulative runs -2250.0000, then -1454.1875, then -658.3750, then 137.4375. Why can a rate be solved for this flow at all?', '["Each of the first three years earns 795.8125, and a flow whose early years are equal always carries exactly one root for the search to find.", "The cumulative reaches 137.4375 inside the concept life of 20.0000 years, which is the crossing the search requires before it will report any rate.", "The net present value of 2047.5653 million USD is positive, and a positive value guarantees a root somewhere inside the band of -99 to 1000 percent.", "It starts negative and later turns positive, so some discount rate brings the discounted total to zero."]'::jsonb, 3, 'Discounting punishes the late positive years harder than the year 0 spend of -2250.0000, so a rate exists; a flow that never turns has none.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 4, 'What makes the Base net present value of 2047.5653 million USD and the tie-back''s 1048.6281 comparable numbers?', '["Both concepts total their capex from the same three fields, which puts the two values onto one basis whatever price each of them was separately run at.", "Both were struck at a discount rate of 10.0000 percent on the same oil price of 70.0000 USD a barrel, which is what puts them on one basis.", "Both scenarios report the status ok, which the engine sets only where two cases share a fiscal basis and one discount rate.", "Both clear a screening hurdle of 15 percent, which puts every case that passes onto one footing."]'::jsonb, 1, 'The rates differ, 40.4321 against 29.5998, and so does the capex, 730.0000 against 2250.0000; what the two values share is the price and the discount rate.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 5, 'Value per million of capex is 1.436477 for the tie-back and 0.910029 for the FPSO. What does that pair establish?', '["The tie-back is worth more money, since 1.436477 is the share of the field''s total value that its capex captures against the FPSO''s 0.910029.", "The FPSO is the more efficient user of capital, since its 0.910029 is spread over a life of 20.0000 years against the tie-back''s 15.0000.", "Every million the tie-back commits works harder, and there is far less of it committed: 730.0000 million USD against 2250.0000.", "The two concepts are interchangeable, since 1.436477 and 0.910029 both sit above zero."]'::jsonb, 2, 'A plan that stops at the tie-back leaves the rest of the field undeveloped rather than earning 0.910029 per million on it, which is why 1048.6281 is less than 2047.5653.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 6, 'Two cash flows differ by a factor of three in every single year. What do their rates of return read?', '["Rates three times apart, since the larger flow returns three times the money on the same shape and a rate carries the size of the money through.", "Whatever their paybacks imply, since payback and rate are both indifferent to size and therefore move together on any pair of flows.", "No rate at all for the smaller of the two, since a flow scaled down towards the floor of -99 percent loses the crossing that the search needs.", "The same rate, because a rate is a percentage and divides out the scale of the flow before it reports."]'::jsonb, 3, 'The tie-back''s 40.4321 percent says nothing about its 730.0000 million USD of capex, which is why 1048.6281 sits under a higher rate than 2047.5653.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 7, 'A published suite case spends 100000 in capex and reports a value of -92616.5020, a rate of -36.6747 percent and the status ok. Why is the status ok?', '["The status records only that the engine priced the case without refusing one of its inputs, so any run that produced a number carries it.", "The flow changes sign, the search found a verified root inside the band of -99 to 1000 percent, and that root simply happens to be negative.", "The rate cleared the floor of -99 percent, and ok marks any rate the band contains.", "The value of -92616.5020 is a real number rather than a null, which is what ok reports."]'::jsonb, 1, 'A rate of -36.6747 percent says the money came back and came back short, which is a real answer; a null with a status would have said something else.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 8, 'Three cases all lose money: one reads -92616.5020 with a rate, one reads -1797.2732 with the status no-root, and one reads -524.1537 with no-sign-change. What separates them?', '["Only the first has a rate: the second changes sign with no rate in the band zeroing it, and the third never changes sign at all.", "Nothing that matters at screening, since all three destroy value and a status records only how far the search ran.", "The size of the loss, since a loss as deep as -92616.5020 always admits a root while -524.1537 leaves nothing to find.", "The discount rate each was struck at, since -1797.2732 and -524.1537 were taken at rates outside the band."]'::jsonb, 0, 'A reader who files all three under a bad rate has lost the difference between a project that returned money badly and one that returned none.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 9, 'A team suppresses any rate below zero on their screening cards, on the grounds that a minus sign looks like an error. What have they given up?', '["Nothing at all, since the EGINA rates run 29.5998, 40.4321, 43.8693 and 14.4152 percent.", "The floor of the search, since hiding rates below zero narrows the band upward from -99 percent.", "The difference between a project that returned money badly at -36.6747 percent and one with no root at all, which the engine marks with a null and a status naming the reason.", "The payback column, since a case with a negative rate never pays back and must be hidden alongside."]'::jsonb, 2, 'The published case at -36.6747 percent carries the status ok on a value of -92616.5020, while the 18.0000 USD a barrel case has no rate to print at all.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 10, 'The Base case reports payback of 3.8273 years. What does that figure record?', '["The cumulative first turned positive inside year 3, moving from -658.3750 up to 137.4375, so the crossing falls part way through the year.", "The discounted cash flow first exceeded the capex of 2250.0000 million USD there, which is the point the engine measures a discounted payback to.", "The third full year of production closed at 137.4375 and the remaining fraction is the share of year 4 added for discounting.", "The engine interpolated between the year 3 and year 4 positions of 137.4375 and 847.0187 to find where the rate of 29.5998 percent is met."]'::jsonb, 0, 'Year 0 spends 2250.0000 and each of the first three years earns 795.8125, which walks the cumulative back up through zero inside year 3.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 11, 'At 30.0000 USD a barrel the concept is worth -898.3507 million USD and the cumulative never reaches zero. What should the payback column carry?', '["The concept life of 20.0000 years, the convention the published zero production case records beside its value of -979.6325.", "The payback of the nearest case that does pay back, 5.7734 years from the 48.0000 USD a barrel run, carried as an upper bound.", "Nothing at all, since a case the engine has refused to price carries neither a payback nor a rate and the status stands for both.", "Never, as a null, which is the measured answer rather than missing data."]'::jsonb, 3, 'Substituting the project life turns the clearest finding a screening case can make into a plausible looking 20.0000; at 18.0000 USD a barrel the answer is the same null.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 12, 'One flow collapses after its cumulative turns and another climbs to 2540.3809 by year 7. Both cross at the same moment. What does payback report?', '["A shorter payback for the climbing flow, since the engine weights the years after the crossing by how much each of them adds.", "A payback for the climbing flow only, since a flow that falls back below zero has its payback withdrawn and reported as never.", "The same figure for both of them, because payback stops looking the moment the cumulative turns positive.", "Two figures that rank with the values, since the flow reaching 2540.3809 is worth more."]'::jsonb, 2, 'The Base case is at 137.4375 when it crosses and 2540.3809 by year 7, and 3.8273 years is the same reading in both.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 13, 'The Low price scenario returns 14.4152 percent and fails a screening hurdle of 15 percent. What did the hurdle reject?', '["A case worth 427.9436 million USD at a discount rate of 10.0000 percent, rejected correctly by the hurdle''s own rule since 14.4152 is below 15.", "A case the engine had already priced as a loss, so the hurdle gave nothing away.", "A case worth less than nothing at the screening discount rate of 10.0000 percent.", "A concept rather than a scenario, since a hurdle is applied to a capex of 2250.0000."]'::jsonb, 0, 'The rule fired correctly, and the 427.9436 million USD it turned down is money the field would otherwise not have had at all.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 14, 'A screening process filters on a hurdle and then sorts the survivors by how far each cleared it. What does that do to the EGINA scenarios?', '["It produces an order that matches the values, since the margin above a hurdle grows with the size of the case and 2047.5653 million USD leads it.", "It places the tie-back above the Base, 40.4321 percent against 29.5998, so 1048.6281 million USD outranks 2047.5653.", "It produces no order at all, since a hurdle returns a pass or a fail and no margin above the threshold to sort on.", "It puts the two concepts on separate lists, since 730.0000 and 2250.0000 are not the same commitment."]'::jsonb, 1, 'The hurdle divides the scale out before it tests anything, and nothing on the page shows that 2047.5653 was the larger amount of money.'),
  ('fdp', 'advanced', 'module', 'm01-the-rate-of-return', 15, 'A screening case is discounted at 10.0000 percent and a hurdle of 15 percent is then applied to its rate. How do the two relate?', '["They are one test stated twice, since a value taken at 10.0000 percent is positive exactly when the rate clears 15 percent and negative when it does not.", "The hurdle replaces the discount rate for any case the engine returns a rate for, so the Base value of 2047.5653 million USD is restated at the higher rate.", "They are two different tests, one charging future money before the value is struck and one a policy applied to the rate afterwards.", "The engine derives the hurdle from the default terms of royalty 12.5000 percent and tax 30.0000 percent."]'::jsonb, 2, 'The Low price case passes the first test, since 427.9436 million USD is positive, and fails the second at 14.4152 percent; which of them decides is a policy somebody set.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 1, 'A published case is negative in every single year and reports the status no-sign-change. Why does no rate exist for it?', '["The search runs from -99 to 1000 percent, and a loss this deep needs a rate somewhere under the floor of that band, which the engine declines to report.", "Discounting shrinks every year by the same factor, so a flow whose years all point one way keeps that sign at every rate the search visits.", "A rate needs at least three producing years to solve against, and a case with no positive year offers nothing to iterate on.", "The engine refuses to price a flow it cannot verify, so the status stands in place of the rate and of the value."]'::jsonb, 1, 'Raising the rate on a flow that only spends makes the loss smaller and never reaches zero; the case that only spends is worth -524.1537.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 2, 'The published zero capex case is worth 717.9604 and reports no-sign-change. What does that status say about the case?', '["It was priced before its capex was entered, so the 717.9604 is a partial result the engine will revise once a capex field carries a figure.", "It is the strongest of the published cases, since a flow positive in every year carries a rate somewhere above the clamp of 1000 percent.", "It failed a completeness check, since a concept with no capex at all is refused by name and returns no value a reader can use.", "It never asked for money up front, so there is no investment for a return to be a return on."]'::jsonb, 3, 'Four of the five no-sign-change cases lose money and this one makes it, and none of the five carries a rate; the 717.9604 is the whole answer.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 3, 'All five published no-sign-change cases withhold a rate. Which figure still reads for every one of them?', '["The net present value, which is defined for any cash flow at any discount rate and is stated in money rather than in percent.", "The payback, which is recorded as the project life whenever the cumulative offers the engine no crossing at all to measure against.", "The rate at the floor of the band, -99 percent, which is what a bounded search reports whenever it finds no crossing above that floor.", "The status alone, since a case with no rate carries no value either and only the reason survives."]'::jsonb, 0, 'On the case with royalty at 100 percent the value of -1464.8989 is the whole story: the state took the gross revenue and the contractor carried the costs.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 4, 'One published no-sign-change case records a rate of 0 and a payback equal to the project life, on a value of -979.6325. What is that 0?', '["A solved root, since a flow with no production crosses zero at the origin and the search confirms it there.", "The floor of the reportable range, substituted for a null so that a screening card always carries a number.", "A convention belonging to that published case, standing in for a flow with no revenue at all rather than reporting a root the engine solved and verified.", "The rate the case would earn once production were restored, held as a placeholder until a profile is entered."]'::jsonb, 2, 'None of the five statuses means zero. A rate of 0 here answers a flow with no revenue, alongside a value of -979.6325 and a payback taken by convention.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 5, 'The tiny capex case is worth 133.3087, its status is above-clamp, and the golden records a root of 15389.6875 percent. What is that status saying?', '["The rate is so large the engine treats it as an overflow and reports the clamp in place of a number nobody could reproduce.", "No return exists for this case at all, and above-clamp is the status used when a search leaves the band without a root.", "The value of 133.3087 is too small for a root to be resolved against it, so the golden carries what the engine declines to state.", "A root exists and it sits above the 1000 percent top of the band the engine searched."]'::jsonb, 3, 'Reporting a root it did not find is how a card ends up carrying a number nobody can reproduce; the second such case reads 2305.7875 on a value of 1074.4692.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 6, 'How can a case worth only 133.3087 carry a root of 15389.6875 percent?', '["The root compounds across the whole project life, so a value as small as 133.3087 spread over the twenty years of the profile reaches four figures of percent.", "The rate divides out scale: a very small outlay followed by a large single year needs an enormous rate to shrink the receipt back down to the outlay.", "The value was struck at 10.0000 percent and the root at the top of the band, and the gap between the two rates is the difference.", "The case earns its whole return in one year, and a rate measured on a single year is multiplied by the years the flow leaves unused."]'::jsonb, 1, 'The money stays small at 133.3087 while the ratio explodes; the second above-clamp case is three fat years on a capex of 20 at 2305.7875 percent.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 7, 'A screening case comes back above-clamp. What is the first thing to check?', '["The band, which should be widened until the root appears so that 15389.6875 percent can be carried onto the management page.", "The value, since a case above the clamp is a marginal one and belongs with the failures until its rate can be stated properly.", "The capex, since a case clearing 1000 percent usually has one that is wrong, missing or entered in the wrong units.", "The discount rate, since a root above the band means the case was struck at a rate too low for the shape the concept implies."]'::jsonb, 2, 'A real development case sits far inside the band, the Base at 29.5998 percent and the tie-back at 40.4321, so a four figure root is a prompt about the inputs.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 8, 'Three of the five statuses withhold a rate for three different reasons. Which reading of them is right?', '["no-sign-change says no root exists, above-clamp says a root exists above the band the search covers, and no-root says the flow changes sign and no rate inside the band zeroes it.", "no-sign-change says the search ran out of iterations, above-clamp says the root sits at the edge of the band, and no-root says the value came out negative.", "no-sign-change says the capex is missing, above-clamp says the capex is too small, and no-root says the price deck is shorter than the profile.", "no-sign-change says the rate is zero, above-clamp says the rate is 1000 percent, and no-root says the rate is somewhere the engine will not name."]'::jsonb, 0, 'None of the three means zero and none of them is a rate. At 18.0000 USD a barrel the status is no-root on a value of -1797.2732 million USD.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 9, 'The published case whose price deck stops before the profile does reports multiple-roots. Where does its second change of sign come from?', '["The last price in the deck is held flat to the end of the profile, and a flat price set against a steadily declining shape drags the late years under zero.", "The missing prices are read as 0, so the uncovered years produce barrels at no price while still carrying their operating cost and turn negative again.", "A second capex phase is inserted where the deck ends, so the flow spends again part way through its life and crosses zero once more.", "The uncovered years are dropped from the profile entirely, which shortens the life below the point at which the cumulative had turned positive."]'::jsonb, 1, 'The flow goes down, then up, then down, so the curve touches zero twice; the case is worth 126.1636 and neither crossing has a claim to be the answer.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 10, 'The golden for that shortened deck case records a root of -52.4425 percent. Why is that still not its rate of return?', '["Another root exists and is equally valid, so the case has no single rate at all and -52.4425 percent is one crossing of two.", "It sits below the floor of the search at -99 percent, so the engine never visited that part of the band and the golden records it from outside.", "A negative root is never reported as a rate by the engine, which is why the status names a refusal in place of carrying the number.", "It was solved on the deck as entered rather than on the profile, so it describes a shorter case."]'::jsonb, 0, 'A negative root is unremarkable arithmetic; what gets a rate withheld is the shape of the flow, and this flow crosses zero more than once on a value of 126.1636.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 11, 'At 30.0000 USD a barrel the concept reads multiple-roots and at 18.0000 it reads no-root. What is the difference between those two answers?', '["How far each value sits below zero, -898.3507 against -1797.2732 million USD, with multiple-roots kept for the shallower of the two losses.", "Whether a payback exists, since the case at 30.0000 USD a barrel pays back inside its life and the case at 18.0000 never does.", "Which search was run, since multiple-roots comes from the band of -99 to 1000 percent and no-root from a second pass made outside that band.", "Whether any rate zeroes the flow at all, since one crosses zero more than once and the other crosses nowhere the band reaches."]'::jsonb, 3, 'Reading the two as synonyms loses the finding. Both are worth stating, -898.3507 and -1797.2732, and neither of them carries a rate.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 12, 'In the studio''s plan path a price deck that does not cover the profile is not padded. What happens instead?', '["The deck is extended at its last price and the case is priced, with the status carrying the extension so a reader can see it was made.", "The uncovered years are priced at 0 and the case comes back multiple-roots, which is the signal to go back and finish the deck properly.", "The case is refused by name: \"the price deck has no price for production year 3: enter a price for every year of the profile\".", "The profile is truncated to the length of the deck and the case is priced over that shorter life, which is worth 126.1636."]'::jsonb, 2, 'Reading a missing price as 0 is what produces the second sign change; the plan path refuses instead, so no value is struck on a deck that stops early.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 13, 'At 18.0000 USD a barrel the concept is worth -1797.2732 million USD. Before the repair the engine reported a rate there. What was the number, and what was it a property of?', '["1000 percent, the top of its own search band, which is a property of the search and not of the cash flow it was run on.", "1000 percent, the highest rate the flow reaches at any point in its life, verified before it was returned.", "A null with no status, which readers filled in by hand because a card would not draw without a number.", "The floor of -99 percent, since a loss this deep drives the search to the bottom of the band."]'::jsonb, 0, 'The flow does change sign, since year 0 spends 2250.0000 and later years earn, so a naive search starts looking and simply never finds a crossing.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 14, 'The clamp of 1000 percent survived a long time on the cards. What made it so hard to notice?', '["It appeared only on cases the engine refused elsewhere as well, so the rate was never the number a reader was actually looking at on the card.", "It moved with the price deck as a solved rate would, so no reader could tell it apart from the 29.5998 percent that the Base case reports.", "It cleared every threshold anyone would set, so it was coloured green on a case whose value of -1797.2732 million USD says the opposite.", "It was printed with no status beside it, and the four statuses that name a refusal arrived only in the repair that removed the clamp."]'::jsonb, 2, 'Nothing about 1000 percent announces that it came from the boundary; the failure is silent, and the contradicting value was printed next to it the whole time.'),
  ('fdp', 'advanced', 'module', 'm02-when-there-is-no-rate', 15, 'What is the tell that a reported rate came from a boundary rather than from a solution?', '["It carries the status ok, which the repaired engine now keeps for a verified root and which the clamped search set on every single run it made.", "It sits exactly on the limit of the search range, where the engine''s genuine answers do not: 29.5998, 40.4321, 14.4152 and -36.6747 percent.", "It appears beside a payback of never, which is the pairing the repaired engine refuses and the clamped search produced freely.", "It is printed to one decimal place while a solved root carries four, which is how a boundary can be spotted on a card."]'::jsonb, 1, 'A solver landing precisely on its own limit has returned a return code; the published tax floor case is the same shape at -944.3201 with the status no-root.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 1, 'The minus 30 percent oil price end of the EGINA sweep is 501.5628. How was that figure produced?', '["By scaling the base of 2047.5653 million USD down in proportion to the price move, which is what would make the two ends of the row symmetric about it.", "By taking the revenue of 16095.0492 down by 30 percent and carrying that difference straight through to the value the case finally reports.", "By discounting the base case at a rate 30 percent higher than 10.0000 percent, which is how the sweep expresses a fall in the price.", "By re-running the whole case with one input changed, royalty, tax, the discount at 10.0000 percent and the production shape all included."]'::jsonb, 3, 'A full re-calculation is why the ends are not symmetric about 2047.5653: 501.5628 and 3593.5679 are not the same distance from it.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 2, 'What combination of moves can the EGINA sweep never show?', '["A move of more than 30 percent in any driver, since the sweep re-runs the case only at the two ends its own convention fixes.", "Two drivers moving together, so a price fall arriving with a capex overrun sits outside the table entirely.", "A fall in the value produced by a rise in a driver, since three of the four drivers raise the value when they themselves rise.", "A move in the production shape, since the sweep changes when the plateau ends each time it scales the profile up or down."]'::jsonb, 1, 'The worst single figure in the table is 501.5628, which is the worst the sweep can produce and not the worst the project can suffer.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 3, 'Ranked by swing the EGINA drivers run Oil Price, Production, CAPEX, OPEX. What does that ordering establish?', '["Which input is most likely to move far enough to matter, which is what would let a drilling capex and a long run oil price be ranked against one another.", "Which input the engine is least certain of, since a wider swing reflects a looser estimate behind the number that was entered for it.", "Which input the value of this case is most exposed to, given a move of the same relative size, 30 percent either way, in each of the four drivers.", "Which input carries the most money, since a swing of 3092.0051 is the share of the revenue of 16095.0492 that the price controls."]'::jsonb, 2, 'A 30 percent move in a drilling capex and a 30 percent move in a long run oil price are not comparable events, and the ranking says nothing about either.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 4, 'A reviewer sets the EGINA price swing of 3092.0051 against a swing reported on a different project. What is wrong with that?', '["Each swing is a share of its own base, so the two are not on one scale.", "The other project was not run on the same terms, royalty 12.5000 percent and tax 30.0000 percent, so only its ends may be compared.", "A swing is comparable only where both cases were discounted at 10.0000 percent, and a sweep does not record the rate it was run at.", "The sweep moves one driver at a time, so only a single driver swing from a single case may ever be set beside another on a page."]'::jsonb, 0, 'As a share of its own base the EGINA price swing is 1.510089, which is the figure that travels between cases; 3092.0051 does not travel.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 5, 'A 30 percent move in price and a 30 percent move in production both scale revenue, yet the price swing is 3092.0051 and the production swing 2839.5965. Why?', '["Royalty at 12.5000 percent and tax at 30.0000 percent fall on the price and not on the volume, which is where the two swings separate.", "A barrel carries its own variable operating cost of 5.0000 USD and a dollar of price does not, so the extra barrels give part of their earnings back.", "The production driver moves only the plateau while the price driver moves every year of the profile, so fewer years carry the volume move.", "The price driver is applied before discounting at 10.0000 percent and the production driver after it, which costs volume part of its effect."]'::jsonb, 1, 'Over the Base life the operating cost is 3049.6464 against revenue of 16095.0492; royalty at 2011.8812 and tax at 3310.0565 take their share of both drivers alike.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 6, 'The published case with no royalty and no tax has a base of 2738.0331, price ends of 1651.9056 to 3824.1606 and production ends of 1735.4539 to 3740.6123. What does it settle?', '["That the government take is what separates the two, since the base moves from 2047.5653 to 2738.0331 once royalty and tax come out of the case.", "That the ordering reverses on a case with no take, which is why the production ends of 1735.4539 and 3740.6123 are quoted beside the price ends.", "That the gap between price and volume is not a fiscal artefact, since price stays the wider driver even with the government take removed.", "That a case with no royalty and no tax carries no variable operating cost either, so both drivers move the value by the same amount."]'::jsonb, 2, 'Price is wider on every published case, this one included: 1651.9056 sits below 1735.4539 at the low end and 3824.1606 above 3740.6123 at the high end.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 7, 'On the published marginal case at 900 capex and 45 a barrel the base is 212.7034, the price downside is -225.0477 and the production downside is -169.4603. What does the pair show?', '["Both downsides take the case below zero, and the price downside goes further because the barrels still being lifted still cost 5.0000 USD each while earning less for each one.", "The case survives a volume shortfall and fails only on price, since -169.4603 is a smaller loss than the base is a gain.", "The two drivers are interchangeable here, since both ends are negative and a value below zero is a failure either way.", "The ordering flips on a marginal case, since -225.0477 is the further from the base and a wider fall means a smaller swing."]'::jsonb, 0, 'On a marginal case the ordering decides whether a project survives at all: the upside ends are 650.4545 and 594.8670 and both downside ends are losses.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 8, 'What would close the gap between the price row and the production row of a sweep?', '["A case with no royalty and no tax, since the government take is what charges the barrels rather than the price they are sold at.", "A larger case, since the example FPSO profile on a base of 10032.1182 carries a wider gap and a smaller case carries none at all.", "A longer life, since discounting at 10.0000 percent weighs the late barrels down and the price move is spread more evenly across the years.", "A case with no variable cost per barrel, since the gap comes from the operating cost the barrels carry."]'::jsonb, 3, 'A case with a higher variable cost per barrel separates them further, and the 5.0000 USD a barrel is what splits 3092.0051 from 2839.5965.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 9, 'The CAPEX row of the EGINA sweep reads 2691.1526 at one end and 1403.9781 at the other. Which end is the overrun?', '["2691.1526, since the sweep prints the ends of every row in order of size and a cost driver always puts its worst outcome first of the two.", "2691.1526, since an overrun raises the capex and the sweep reports the higher value against the higher spend on the row.", "1403.9781, the plus 30 percent end of the row, and 2691.1526 is what the case is worth if the capex comes in 30 percent under.", "Neither of them, since a capex move changes the deepest cash position of -2250.0000 and not the value the sweep reports."]'::jsonb, 2, 'The sweep prints minus and then plus rather than in order of size, so this row runs high to low; read the label before the value.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 10, 'Capex swings the value by 1287.1745 and operating cost by 323.8828 on the same relative move. What accounts for the difference?', '["Capex lands in year 0 before a barrel is produced, where discounting touches it least, while operating cost spreads across the producing years and the later portions count for less.", "Capex is the larger input and the sweep moves each by 30 percent, so the two swings sit in the same ratio as the inputs.", "Capex is charged before royalty and tax while operating cost is charged after them, so the terms absorb part of the opex move.", "The capex bar is symmetric about the base of 2047.5653 and the operating cost bar is not, which stretches the capex swing."]'::jsonb, 0, 'As a share of base that is 0.628637 against 0.158179, and the capex move works directly on the deepest cash position of -2250.0000.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 11, 'A chart ranks the four bars by their right hand end rather than by their swing. What does that do?', '["It puts the base of 2047.5653 in the middle of the chart, which is where a sweep is read from in any case and costs its reader nothing at all.", "It reverses the ranking of Oil Price and Production, whose right hand ends of 3593.5679 and 3467.3636 sit fairly close together on the page.", "It sorts the two cost drivers as though their overruns were upsides, since the CAPEX and the OPEX rows both run from high to low.", "It drops OPEX from the chart, since its ends of 2209.5067 and 1885.6239 both sit above the right hand end of the capex row."]'::jsonb, 2, 'The swings are 3092.0051, 2839.5965, 1287.1745 and 323.8828, and only a swing puts the four rows of the sweep on one footing.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 12, 'On the published marginal case the capex ends are 470.1383 and -44.7315. What does reading that row backwards produce?', '["A case that fails on a cost saving, since 470.1383 is the end the sweep prints first and a first end is always taken to be the adverse one on a row.", "No error at all, since both ends are correct runs of the case and a base of 212.7034 sits between them whichever way round they are read.", "A swing read at the wrong sign, which the share of base of 0.628637 corrects as soon as the row is ranked against the other three.", "A case that fails on a cost overrun read as a case that thrives on one, since the overrun end of that row is the end that sits below zero."]'::jsonb, 3, 'An overrun of 30 percent takes that case from 212.7034 down to -44.7315, and the direction of the row is the only thing that says so.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 13, 'Why may the figure 501.5628 not be labelled a P90 NPV?', '["It is one conditional run, and a P-label belongs to a reserves distribution one fluid at a time, such as an oil P50 of 130.0000 MMbbl.", "It is the low end rather than the high end, so it would have to be labelled a P10 NPV to match the convention.", "A P-label may be carried by a value in money, but only once the sweep is re-run on a distribution of prices.", "A P90 is fixed at a different exceedance from the 30 percent the sweep moves, so the label is right at another figure."]'::jsonb, 0, 'Calling it a P90 asserts that a 30 percent price fall has a particular chance of being exceeded, and the sweep contains no such claim; a gas P50 of 70.0000 Bcf is what a P-label describes.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 14, 'A manager reads the eight ends of a tornado as the range the project could land in. What is missing from that reading?', '["The base of 2047.5653 million USD, which the chart leaves out and which a reader needs before either end of any row can be placed at all.", "The upside beyond 30 percent, since the eight ends are conditional on the sweep''s own convention and a driver can move a good deal further than that.", "Every case where two drivers move together, which the sweep never runs and which on a marginal case is worse than either end alone.", "The discount rate, since every one of the eight ends was struck at 10.0000 percent and a range of outcomes has to be stated before it is discounted."]'::jsonb, 2, 'On the marginal case the price downside of -225.0477 and the capex overrun end of -44.7315 are both in the table, and the case where both happen is not.'),
  ('fdp', 'advanced', 'module', 'm03-what-a-sensitivity-says', 15, 'What is a tornado chart genuinely good for?', '["Sizing the risk carried by a case, since the widest bar of the four names the driver most likely to move by an amount that hurts the value of it.", "Ranking the four drivers of one case by their arithmetic leverage, as a work list for where to spend effort on tightening an estimate.", "Testing whether the inputs behind a case were right, since a base that is wrong shows up as a set of ends that will not balance.", "Bracketing the outcome, since the widest end and the narrowest end mark the limits the case can reach on any combination of moves."]'::jsonb, 1, 'A driver with a swing of 323.8828 does not repay much study on this case and one with a swing of 3092.0051 does.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 1, 'ODUDU-2 carries planned costs of 2400000, 5200000, 8600000, 12500000 and 3300000, and reports an earned value of 8360000 at every as-of date. Where does 8360000 come from?', '["The planned costs of the tasks that have started, since a task enters the earned value at its full budget once work opens on it.", "The spending column added up, 2510000 and 3180000 and 2450000, which is what the project has actually paid out so far.", "Each task''s own budget taken at that task''s own percent complete and then summed, which is why no date moves it.", "The share of the 32000000 budget the calendar had scheduled by 2028-12-31."]'::jsonb, 2, 'Front end engineering at 100.0000 percent, Detailed design at 65.0000 percent and Procurement at 30.0000 percent build the 8360000; the spending column builds 8140000 and the planned costs build 32000000.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 2, 'ODUDU-2 reports a cost index of 1.027027 on every one of its five as-of dates. What has that number measured?', '["An earned value of 8360000 against an actual cost of 8140000, so the work that has been done was bought for slightly less than the budget attached to it.", "An earned value of 8360000 against a planned value of 10178668, so the project is a little ahead of what the plan asked for.", "An actual cost of 8140000 against a planned value of 10178668, so spending is running under what the calendar had scheduled.", "An earned value of 8360000 against the budget at completion of 32000000, so about a quarter of the job has been bought."]'::jsonb, 0, 'Nothing in the cost index is about time: 8360000 over 8140000 is 1.027027 whether the date is 2028-01-01 or 2031-01-01, while the schedule reading on those two dates is none and 0.261250.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 3, 'A published three task case reports planned value 1750, earned value 1500 and actual cost 1450, with a schedule index of 0.857143 beside a cost index of 1.034483. How does one earned value produce two different answers?', '["The schedule index is taken at the as-of date while the cost index is taken over the whole window, so the two cover different stretches of the same work.", "The cost index carries the plan of 1750 inside it as well, which is why the two readings differ by the amount the plan and the spending differ by.", "The engine builds the schedule index from the planned costs and the cost index from the invoices, so the two are computed over different task lists.", "It is divided by two different denominators, 1750 for time and 1450 for money."]'::jsonb, 3, '1500 over 1750 is 0.857143 and 1500 over 1450 is 1.034483: a report that quotes a single index has answered one of the two questions and left the other open.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 4, 'ODUDU-2 reports a schedule index of 2.437529 at 2028-06-30 and 0.439389 at 2029-06-30, with an earned value of 8360000 and an actual cost of 8140000 on both rows. What happened to the project between those dates?', '["Work stopped for the best part of a year on a project that had been running ahead of its plan, which is what a fall from 2.437529 to 0.439389 records.", "Nothing: the planned value rose from 3429703 to 19026406 as the calendar moved, and the plan''s own demand ran past the work.", "The budget at completion grew as tasks were added, so the same earned value now covers a smaller share of a bigger job.", "Spending overtook progress, which drags a schedule index down once the actual cost of 8140000 has passed the earned value."]'::jsonb, 1, 'Earned value and actual cost are unmoved across all five as-of dates; planned value is the only figure the date reaches, and the schedule index moves with it.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 5, 'At an as-of date of 2031-01-01 ODUDU-2 reports a planned value of 32000000, which is exactly its budget at completion. Why do the two meet there?', '["Every planned window has closed by then, so the whole budget had been scheduled and the plan has nothing left to ask for on a later date.", "The project finished on 2031-01-01, so the plan and the work had both run their course by the time the question was asked.", "Commissioning runs to 2030-10-31 and the engine stretches that last window to the year end, which rounds the planned value up to the whole budget.", "The planned value is set to the budget at completion once the earned value of 8360000 has stopped moving, since nothing further can be phased."]'::jsonb, 0, 'Commissioning is the last window and it shuts on 2030-10-31; with every window closed the planned value equals the 32000000 the task list sums to, and the schedule index reads 0.261250.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 6, 'ODUDU-2''s completion ratio stands at 0.261250 on all five as-of dates. What is it a ratio of?', '["An earned value of 8360000 over the planned value the calendar had reached, which is 10178668 on the date the project is usually reported.", "The share of the five tasks that are finished, since Front end engineering stands at 100.0000 percent and the rest are still running.", "An earned value of 8360000 over a budget at completion of 32000000, a sum of planned costs that no date changes.", "The actual cost of 8140000 over the same 32000000, which is the money paid out."]'::jsonb, 2, 'Add 2400000, 5200000, 8600000, 12500000 and 3300000 and the denominator is 32000000 on every date, so 8360000 over it gives 0.261250 on every date.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 7, 'A completion ratio can never read above one and a schedule index can. What in the arithmetic makes that so?', '["The engine clips any schedule index above one before it is displayed, and applies no such clip to the completion ratio it prints beside it.", "Earned value cannot pass the budget at completion because progress stops at 100.0000 percent, while the planned value it is divided by stays smaller than that budget until the last window closes.", "The completion ratio counts finished tasks only, so it stops at the five in the list, while the schedule index counts money and carries no ceiling at all.", "The schedule index carries the cost index inside it, so a project bought under its budget at 1.027027 can be pushed above one on the schedule reading."]'::jsonb, 1, 'One task 90.0000 percent done half way through its window reads a schedule index of 1.795082 against a completion ratio of 0.900000 at the same moment.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 8, 'One task 90.0000 percent done half way through its own window reports a schedule index of 1.795082. What does that number claim?', '["That the task has earned nearly twice its own budget, which is why the completion ratio standing beside it reads 0.900000.", "That the task will finish well ahead of its window, since the index scales the time still to run by the pace already achieved.", "That the money was spent efficiently, since an index above one is what a project buys when its cost index also reads above one at 1.027027.", "That the work earned to this date is worth more than the plan had scheduled to this date."]'::jsonb, 3, 'It says nothing about money and nothing about the finish: the completion ratio on the same task at the same moment is 0.900000, and the task still has half its window to survive.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 9, 'ODUDU-2 at an as-of date of 2028-01-01 reports an earned value of 8360000, an actual cost of 8140000 and no schedule index at all. Why is there no index on that row?', '["The engine withholds the index until Front end engineering opens on 2028-01-10, because an earned value of 8360000 cannot be real before the first window.", "The index would be unbounded, so the engine prints the cost index of 1.027027 alone.", "No window has opened by that date, so the planned value is 0 and there is no denominator to divide by.", "The as-of date falls before the project start, so every figure on that row is withheld and the 8360000 shown is carried up from the row beneath it."]'::jsonb, 2, 'Earned value is not time-phased and reads 8360000 on every date, while the planned value at 2028-01-01 is 0; a published case read at 2025-12-31, before its window opens, reports the same absence.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 10, 'An as-of date typed as last Friday is refused with ProjectControlsInputError: "asOf is not a valid date: last Friday". Why is no default date put in its place?', '["The engine has no clock to fall back on, and a date read as UTC midnight lands on the day before anywhere west of Greenwich.", "A quietly substituted date would make every index on the report impossible to reproduce, because a planned value and a schedule index are a pair of a project and a date.", "A phrase like that could mean any of the five dates on the report, so the engine asks for one of 2028-01-01, 2028-06-30, 2028-12-31, 2029-06-30 or 2031-01-01.", "The refusal protects the earned value of 8360000 and the actual cost of 8140000, which would otherwise be recomputed against the wrong week of the plan."]'::jsonb, 1, 'ODUDU-2 at 2028-12-31 reports a planned value of 10178668 and a schedule index of 0.821326 whenever it is run, this year or in five years, because nothing in the calculation asks what today is.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 11, 'A reviewer sets a status pack reading 2.437529 beside a live screen reading 0.439389 and concludes the project has collapsed. What is wrong with that reading?', '["The two figures carry different as-of dates, 2028-06-30 and 2029-06-30, and the earned value behind both of them is the same 8360000.", "The pack quoted the cost index and the screen the schedule index, which is why one reads above one and the other well below it.", "The screen reports the completion ratio of 0.261250 rescaled to the window still to run, so the two numbers were never the same measurement.", "The pack was run before Procurement was costed at 8600000, so its denominator was missing a task the screen now carries in full."]'::jsonb, 0, 'Planned value moves from 3429703 to 19026406 between those dates while no work is done and no money is spent, so the fall is the calendar and not the team.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 12, 'Which figures on an earned value report does the as-of date reach?', '["All five, since each figure is a measurement taken at the stated date and a later date finds more work done and more money spent.", "The earned value and the planned value, since both are built from the task windows, while the actual cost of 8140000 comes from what was invoiced.", "The two indexes alone, since the three money figures of 10178668, 8360000 and 8140000 are properties of the task list rather than of the date.", "The planned value, and the schedule index through it."]'::jsonb, 3, 'Across the five dates the earned value stays 8360000 and the actual cost stays 8140000 for a cost index of 1.027027, while the planned value runs 0, 3429703, 10178668, 19026406 and 32000000.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 13, 'A published case read at 2027-06-30, after its last window has closed, reports a planned value of 1000 against an earned value of 600 for an index of 0.600000. What can that denominator no longer say?', '["That the work is late, since a denominator that has reached the whole budget can only push the index above one from that point onward.", "That the work is early, because the plan has run out of time to schedule anything and the denominator now holds the whole budget.", "That any work is left to do, since 0.600000 on a closed window is the share of the budget abandoned.", "That the cost is under control, since the case reports no actual cost at all."]'::jsonb, 1, 'Before the last window closes the planned value is smaller than the budget at completion, and that gap is the only room a schedule index has to read above one.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 14, 'ODUDU-2''s schedule index and completion ratio both read 0.261250 at 2031-01-01 and disagree on every earlier date. Is that agreement reassuring?', '["Yes: two measurements built on different denominators arriving at one figure is the reconciliation that shows the task list and the calendar agree.", "Yes: an index that has settled onto 0.261250 has stopped moving, and so has the schedule.", "No: they meet only because the planned value has reached the budget at completion of 32000000, which means every window has shut.", "No: they meet because the earned value of 8360000 is frozen in both numerators."]'::jsonb, 2, 'At 2028-06-30 the same two numbers read 2.437529 and 0.261250; the meeting at 2031-01-01 says the plan ran out of calendar, not that the work was finished.'),
  ('fdp', 'advanced', 'module', 'm04-earned-value-to-a-date', 15, 'Two published cases read half way through a single window report planned value 500 against earned value 500 for an index of 1.000000, and planned value 500 against earned value 250 for 0.500000. How was the 500 of planned value arrived at?', '["Each costed task''s budget is spread across that task''s own planned window and then cut off at the as-of date, so half a window carries half the budget.", "The budget at completion is divided between the tasks whose windows are open, which puts half of a two task plan into the planned value.", "The earned value is rounded to the nearest planned figure once the as-of date falls inside a window, which is why 500 appears on both rows.", "The plan books a task''s whole budget on the day its window opens, so any window that opened before the as-of date carries all of its cost."]'::jsonb, 0, 'The same rule gives ODUDU-2 a planned value of 3429703 at 2028-06-30 and 10178668 at 2028-12-31 out of the same five windows.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 1, 'A planned cost pasted with its currency symbol is now refused as "Rig move: planned cost is not a number: $1,200". Before this course''s repair, what became of that task?', '["It was dropped from the task list, so the budget at completion fell and a warning named the row that had been removed from it.", "It counted as zero and stayed in the list with its name and its dates, contributing nothing to the planned value, nothing to the earned value and nothing to the budget at completion.", "The symbol and the separator were stripped and the figure read as 1200, which is what a paste out of a spreadsheet was assumed to carry.", "The whole project was refused, which is why one unreadable figure used to leave a status pack with no indexes printed on it at all."]'::jsonb, 1, 'Every number downstream still printed, which is worse than a blank cell: correct arithmetic on a task list that is missing money is the hardest error to find.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 2, 'On a task list whose planned costs are 2400000, 5200000, 8600000, 12500000 and 3300000, the Procurement figure of 8600000 is read as zero. What happens to the completion ratio of 0.261250?', '["It rises, because the whole 8600000 leaves the budget at completion of 32000000 while the earned value of 8360000, built from the three tasks that carry progress against them, stays exactly where it was.", "It holds at 0.261250, because earned value and the budget at completion both lose the same 8600000 and the ratio between them is unchanged.", "It reports as none, because a planned cost the parser could not read leaves the budget at completion with no readable value at all to divide into.", "It falls to 0.247009, because Procurement stood at 30.0000 percent, which is above the project''s own 0.261250, so the numerator loses 2580000 while the denominator loses 8600000."]'::jsonb, 3, 'Procurement earned 2580000 of the 8360000, so the numerator falls to 5780000 and the denominator to 23400000. The new ratio looks perfectly ordinary, which is the danger: 8600000 has gone out of the 32000000 and nothing on the report says so.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 3, 'Procurement runs 2028-08-01 to 2029-07-31, so its window is open at 2028-12-31. What does a Procurement cost read as zero do to the schedule index of 0.821326?', '["It raises it, because part of the 8600000 sits inside the planned value of 10178668 and a smaller denominator lifts the index for no reason a reader can see.", "It lowers it, because the task keeps its window and the planned value keeps the full share it was carrying before.", "It leaves it at 0.821326, because the planned value is phased from the task windows alone, and a planned cost feeds only the budget at completion and the ratio built on it.", "It removes it, because the engine withholds the schedule index once any costed task fails to parse its planned cost."]'::jsonb, 0, 'Planned value is time-phased from each task''s budget across that task''s own window, so taking 8600000 out of the sum shrinks the denominator that produced 0.821326.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 4, 'Fabrication and Commissioning carry actual costs of 0 and the engine is content, while a cost of -100 is refused as "Credit: planned cost may not be negative: -100". What is the guard checking?', '["Whether the cost is consistent with the task''s percent complete, so a zero is allowed only on a task that also stands at 0.0000 percent.", "Whether the cost falls inside the budget at completion of 32000000, which a negative figure cannot do and a zero does trivially.", "Readability and sign, and nothing else: a zero is a number somebody typed, and a negative budget has no meaning in the arithmetic that follows it.", "Whether the figure can be parsed, so the zero passes and the negative is caught further downstream by the earned value sum rather than by the guard."]'::jsonb, 2, 'Fabrication and Commissioning stand at 0.0000 percent with actual costs of 0, and they still carry planned costs of 12500000 and 3300000 into the budget at completion.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 5, 'One costed task with no planned dates is added to ODUDU-2. What does the engine report for the schedule index, and on what grounds?', '["A schedule index built from the tasks that are dated, with a warning that one task was left out of the planned value sum.", "A schedule index of 0.256839, which is the completion ratio the engine falls back to whenever the phasing cannot be completed for every task.", "No schedule index and no basis line at all, since the engine states a basis only on the reports where the phasing succeeded.", "No schedule index, with the reason given: \"1 costed task carries no planned dates, so planned value cannot be time-phased\"."]'::jsonb, 3, 'The message counts the tasks that are missing dates, which is a work instruction: date them from the plan, or take their cost out if they are not in the plan yet.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 6, 'Why does the engine refuse to put a zero into the planned value sum for a costed task that carries no window?', '["A zero would be counted twice later on, once the task is dated and its budget enters the phased sum a second time under its own window.", "A zero would claim the plan had scheduled none of that money by the as-of date, which is a statement about the schedule nobody made.", "A zero would drag the earned value down with it, since the planned value and the earned value are built in the same pass over the task list.", "A zero is reserved for a task whose window has not opened yet, and reusing it would leave the two situations impossible to tell apart on a report."]'::jsonb, 1, 'The earned value stays where it is while the denominator shrinks, so a team reads a healthier index than 0.821326 because a date was missing.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 7, 'With a planned cost of 900000 at 10.0000 percent and no dates on it added, ODUDU-2 reports a budget at completion of 32900000, an earned value of 8450000 and a completion ratio of 0.256839. Why do those three survive when the schedule index does not?', '["They were computed before the undated task was read, so they carry the original five tasks and the new one is excluded from all three.", "They are reported at task level rather than project level, and only the project level figures are withheld when an input is missing.", "They are sums of money with no calendar in them, while a planned value needs a window on every costed task before it can be phased to a date.", "The engine substitutes the project start date for a missing window when it totals money, and declines to substitute it when it phases the plan."]'::jsonb, 2, 'Earned value, actual cost, the budget at completion, the completion ratio and the cost index all survive an undated task; the planned value and the schedule index do not.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 8, 'A window whose end date falls before its start date and a window of zero length arrive in the same task list. What does the engine do with each?', '["It refuses the backwards window as \"Backwards: the planned end date is before the planned start date\", and it accepts the zero length window and handles it.", "It refuses both, since a window that does not run forward for at least one day cannot carry a share of its task''s budget.", "It accepts both, and each contributes its task''s whole budget to the planned value from the day the window is dated.", "It reads the backwards window in whichever order the two dates make sense, and drops the zero length window out of the planned value."]'::jsonb, 0, 'A published zero length window read at 2026-06-01 reports planned value 0, earned value 100 and no schedule index, so the task is either not started or finished.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 9, 'A project with no costed task at all is read. Which outputs does the engine withhold, and what does it say?', '["The planned value and the schedule index only, since the earned value and the cost index can still be built from the actual costs that were paid out.", "The schedule index, the cost index and the percent complete, with the basis stated: \"no costed task, so there is no planned value\".", "Nothing at all: it reports zeros right across the row, because a task list with no money in it really has earned nothing against nothing.", "The whole report, since an earned value calculation with no money on either side of its two ratios has no figures left at all to print."]'::jsonb, 1, 'A published empty task list read at 2026-07-02 reports no planned value, earned value 0, actual cost 0, no schedule index and no cost index.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 10, 'Before the repair, what appeared on a status card for an index that had no denominator?', '["A blank cell, which left the reader to work out from the task list whether the project had been costed at all.", "A zero under a heading saying the project was behind schedule, which at least pointed at the missing input instead of flattering it.", "A clean 1.00 under a heading saying the project was under budget, and a percent complete that came back as the string NaN, which one card read as a zero and labelled behind schedule.", "The completion ratio in place of the missing index, so a project with no costed task borrowed its progress figure and printed it twice."]'::jsonb, 2, 'A ratio of one is what a perfectly run project earns, so the project with no numbers in it printed the more reassuring of the two labels.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 11, 'Progress of 150 is refused as "Overdone: percent complete must be between 0 and 100, not 150". What would accepting it have done?', '["The task would be treated as finished at 100.0000 percent and the surplus carried forward to the next task in the list.", "The schedule index would fall, since planned value cannot phase more than a task''s budget and the excess would land in the denominator instead.", "Nothing measurable, since earned value is capped at the budget at completion of 32000000 and the excess is discarded before the indexes are formed.", "The task would earn half again its own budget, lifting the earned value above the budget at completion and the completion ratio above one."]'::jsonb, 3, 'A ratio whose whole meaning is the share of the job that is done would be reporting more job than exists, and the cost index would rise along with it.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 12, 'A progress figure typed as the word half is refused rather than read as zero. What is the argument for refusing it?', '["A task that may be almost finished would enter the earned value at nothing and drag the schedule index down with no sign on the report of why.", "A zero would break the range check, since a figure the parser cannot read has no position between 0 and 100 to be checked against.", "A zero would raise the cost index, since the actual cost of that task stays in the denominator while its earned value disappears.", "A zero would be corrected at the next report, since the engine carries the last readable progress figure forward for any task whose newer figure it cannot parse."]'::jsonb, 0, 'The message names the task and quotes the text back: "Half: percent complete is not a number: half".'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 13, 'Procurement is typed at 30.0000 percent on a task where nothing has actually started. What does the engine do with that figure?', '["It refuses it, since a task with no actual cost recorded against it cannot report progress above 0.0000 percent.", "It accepts it and flags it, since 30.0000 percent on a window that opened 2028-08-01 is checked against the share of that window already elapsed.", "It accepts it, because the guard is a range check and not a truth check, and the earned value of 8360000 and the schedule index of 0.821326 carry the claim without questioning it.", "It accepts it and leaves the earned value alone, since only tasks with spending behind them are allowed into the earned value sum."]'::jsonb, 2, 'Acceptance means the figures were readable and in range; earned value is only as good as the progress typed into it, and the refusals guard the arithmetic rather than the judgement.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 14, 'One published row reports a schedule index of none beside a cost index of 0.000000, and another a schedule index of 0.000000 beside a cost index of none. What separates the two kinds of entry?', '["A 0.000000 is a division that happened, an earned value of 0 over an actual cost of 20, and a none is a division that could not happen at all.", "A 0.000000 is printed when the figure rounds below the sixth decimal, and a none when there is no figure to round.", "A 0.000000 belongs to a task that has started and earned nothing while a none belongs to one that has not started, so the pair is about timing.", "A 0.000000 is how the schedule reading is withheld and a none how the cost reading is withheld, since the two columns use different conventions."]'::jsonb, 0, 'Tasks without costs read planned value none, earned value 0 and actual cost 20; no actuals and no progress reads planned value 50, earned value 0 and actual cost 0.'),
  ('fdp', 'advanced', 'module', 'm05-what-earned-value-refuses', 15, 'A portfolio roll-up averages the schedule indexes of its projects and counts every none as a zero. What has it produced?', '["A conservative average, since treating an absence as the worst case is the safe reading whenever a project''s basis is unknown.", "An average dragged down by projects that were never costed, and counting them as one instead would hide the same projects the other way.", "A correct average of the projects that did report, since a zero adds nothing to a sum and only the count of projects has changed.", "An average that agrees with the completion ratios, since a project with no planned value has still earned nothing against its budget at completion."]'::jsonb, 1, 'A schedule index of 0.000000 says a plan asked for 50 and nothing was earned against it, and a none says there is no plan to ask anything; the missing entries were never measurements.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 1, 'EGINA''s facility screening estimate is 1363.3524 million USD for the FPSO. Which figure in the plan should it be set beside?', '["The concept''s total capex of 2250.0000 million USD, which is the figure the plan reports as the cost of the whole development.", "The cost items'' CAPEX total of 2250.0000 million USD, since both of those are totals the engine computed rather than figures somebody typed in.", "The FPSO hull and topsides line of 1180.0000 million USD, which is the only cost item the plan raises against the vessel itself.", "The concept''s facilities field of 1350.0000 million USD, a gap of 13.3524."]'::jsonb, 3, 'Setting 1363.3524 against 2250.0000 compares one facility with a development that also drills 520.0000 of wells and lays 380.0000 of subsea.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 2, 'Which of the plan''s cost items correspond to the concept''s facilities field of 1350.0000 million USD?', '["FPSO hull and topsides at 1180.0000 together with Subsea system at 380.0000, the two lines raised against the vessel and its tie-ins.", "FPSO hull and topsides at 1180.0000 together with Mooring and installation at 170.0000.", "The Construction phase total of 1180.0000 and the Installation phase total of 550.0000, which is how the engine groups that same money.", "The two largest lines the plan carries, 520.0000 and 1180.0000."]'::jsonb, 1, '1180.0000 and 170.0000 make 1350.0000; Development drilling of 520.0000 matches the drilling field and Subsea system of 380.0000 matches the subsea field.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 3, 'The concept''s capex is 2250.0000 million USD and the cost items'' CAPEX total is 2250.0000 million USD. What does that agreement tell a reader?', '["That the cost items are derived from the concept''s three capex fields, so the two totals cannot differ however the lines are entered.", "That the concept''s drilling, facilities and subsea fields were filled in from the cost items once the budget lines had been priced.", "That this plan was costed against the concept it is running, which is a result somebody earned rather than something the studio guarantees.", "That the plan has been validated, since the studio compares the two totals against each other before it scores a plan complete at 100 percent."]'::jsonb, 2, 'They remain two different numbers gathered by two different people for two different purposes, and a plan where they differ has a question in it.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 4, 'The plan''s cost items include a Decommissioning provision of 260.0000 million USD typed as ABEX. Where does it appear in the engine''s totals?', '["In neither of them: the CAPEX total is 2250.0000 and the OPEX total is 95.0000 a year, because the screening case carries capex and operating cost only.", "In the CAPEX total, which is why 2250.0000 stands above the drilling, facilities and subsea fields taken on their own.", "In the OPEX total of 95.0000 a year, since the line sits in the Operate phase alongside the operations and the maintenance lines.", "In the facility screening estimate of 1363.3524, which is the one figure in the studio that carries a decommissioning number."]'::jsonb, 0, 'A line can be in the plan, correct, and absent from the number the plan reports.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 5, 'What does the facility screening estimate carry that the plan''s CAPEX total does not?', '["The Decommissioning provision of 260.0000 million USD, which the screening picks up from the plan''s own cost items and prices on the nameplate.", "A decommissioning figure of 204.5029 million USD for the FPSO, which is 0.150000 of the capex that facility carries.", "The operating cost of 95.0000 million USD a year, which the screening derives from the type and the size the facility was entered at.", "The subsea capex of 380.0000, since the tie-ins land on the same vessel."]'::jsonb, 1, 'The screening gives every facility a decommissioning figure at 0.150000 of its capex: 204.5029 on 1363.3524, and 388.3805 on the debottlenecked case.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 6, 'EGINA''s network says the work must take 870 days and the dates typed on its activities span 933 days. What is the 63 days between them?', '["Contingency the planner has set aside, which is why the calendar is drawn longer than the logic requires it to be.", "The duration of the activities that carry float, since a2 and a5 hold 180 days each and a6 holds 480 days of its own.", "A counting error from subtracting two timestamps across a daylight saving change, which the whole day count was brought in to remove.", "Float already spent, sitting inside somebody''s start dates and available to nobody."]'::jsonb, 3, 'Reading the 63 days as contingency double counts it, because the calendar has spent it and the plan has not recorded spending it.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 7, 'Subsea installation carries 480 days of float and the calendar carries 63 days. Which of the two can the project actually spend?', '["The 480 days, because an activity with float can slip that far without moving the end date, while the 63 days are already committed to start dates.", "Both, since 480 days of logic float and 63 days of calendar float add up to the slack the schedule is holding in total.", "Neither, since a float measured as late start minus early start is an artefact of the backward pass rather than a stretch of time anybody can spend.", "The 63 days, since the calendar is the only place a date can actually move and a6 sits off the critical path in any case."]'::jsonb, 0, 'The critical path of a1, a3, a4, a7 and a8 at 870 days cannot slip at all, a2 and a5 carry 180 days each, and a6 carries 480.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 8, 'A plan can state its own duration in three ways. Where does the 36 months between a sanction of 2027-04-01 and a first oil of 2030-04-01 come from?', '["From the critical path, since 870 days of work dated forward from 2027-04-01 lands on the concept''s own first oil date.", "From the calendar span of 933 days on the activities, rounded to whole months and dated from the sanction milestone.", "From the concept type, dated from the concept start, which is a different mechanism from the network''s 870 days and the activity dates'' 933 days.", "From the machine clock at the moment the concept was created, which is why a concept schedule has to be re-dated every time somebody reopens the plan."]'::jsonb, 2, 'The concept schedule is dated from the concept and never from a clock, so a plan carries three statements about its own duration produced three different ways.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 9, 'Before the repair every one of EGINA''s eight activities read critical at float 0. What does a network of eight critical activities actually indicate?', '["That every activity genuinely sits on the longest path, which is what a plan with no float anywhere in it looks like.", "That nothing has been linked: with no dependencies typed every activity starts on day 0, and the network is only as long as its longest single activity.", "That float was computed as late finish minus early finish instead of late start minus early start, which returns 0 on every row.", "That the schedule is fully resourced, since a critical path method run over a plan with its resources levelled marks every activity in it critical by design."]'::jsonb, 1, 'A path of five out of eight with 480 days of float sitting on Subsea installation is a schedule somebody can manage; a list of eight critical activities is not.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 10, 'The Base scenario on the concept''s capex returns an NPV of 2047.5653 million USD and the plan''s own cost items at the same price return 2047.5653. What does the difference of 0.0000 mean?', '["That the plan was costed against the concept it is running, which is a reconciliation somebody performed rather than an identity the engine enforces.", "That the engine runs the scenario once and reports it twice, so the two figures are one calculation printed under two headings.", "That the cost items are ignored by the economics, which reads the concept''s three capex fields and nothing else.", "That the plan is complete and valid at 100 percent, which is the check that holds the two NPVs together."]'::jsonb, 0, 'A difference of zero earned by reconciliation is a finding; a difference of zero assumed in advance is nothing at all.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 11, 'Which pair of EGINA''s numbers can never be reconciled at all, whatever a reader does with them?', '["The concept''s capex of 2250.0000 and the facility screening estimate of 1363.3524, because one is a class 5 figure and the other a budget.", "The network''s 870 days and the calendar''s 933 days, two counts of one schedule.", "The oil P50 of 130.0000 MMbbl and the gas P50 of 70.0000 Bcf, because adding them gives 200.0000 of nothing.", "The schedule index of 0.821326 and the completion ratio of 0.261250, because one moves with the as-of date and the other never moves."]'::jsonb, 2, 'Each of the other pairs has a stated relationship to work through; two fluids in two different units have none, and the totals are kept one fluid at a time.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 12, 'A schedule index of 0.821326 and a completion ratio of 0.261250 are reported for the same project on the same date. Which of the two is wrong?', '["The completion ratio, since a figure that stands at 0.261250 on every as-of date cannot be describing a project that is moving.", "The schedule index, since a project only a quarter of the way through its budget cannot be running at 0.821326 of its plan.", "Both of them, since two ratios sharing one earned value ought to agree once they are put over the same denominator.", "Neither: both are correct readings of the same earned value."]'::jsonb, 3, 'One divides by a planned value that moved with the date and the other by a budget at completion that never moves, and reconciling them by dropping one throws the information away.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 13, 'At 18.0000 USD a barrel the FPSO scenario returns an NPV of -1797.2732 million USD. What does it report for the rate of return and for the payback?', '["No rate of return at all, with a status of no-root, and a payback of never, which is the honest reading of a case that does not return its money.", "A rate of 1000 percent, the upper edge of the band the engine searches, and a payback of never.", "A negative rate, since an NPV of -1797.2732 has to correspond to a rate below the discount rate of 10.0000 percent.", "No rate, with a status of no-sign-change, and a payback equal to the concept''s life of 20.0000 years."]'::jsonb, 0, 'A search that clamped at its own boundary used to print 1000 percent here, in green, on a scenario that never pays back.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 14, 'EGINA''s register carries a Host government approval risk with an impact of 5 and a cost impact of 400.0000 million USD. What does it contribute to the exposure of 269.0000 million USD?', '["400.0000, the whole cost impact, carried undiscounted.", "0.0000, because its probability is missing, so there is no factor to multiply the cost impact by.", "108.0000, the same contribution the critical risk makes, since an unscored risk is banded with the highest risk that is scored.", "A share of the 1145.0000 the five cost impacts add to, since the exposure spreads the register''s total across its rows."]'::jsonb, 1, 'The factors run by probability, 1 giving 0.05 up to 5 giving 0.85, and a risk with no probability has no factor; the exposure of 269.0000 is not the 1145.0000 the impacts add to.'),
  ('fdp', 'advanced', 'module', 'm06-reading-a-plan-against-itself', 15, 'Two figures in a plan disagree, and a reviewer proposes dropping one of them so the document reads clean. What does that lose?', '["Nothing, provided the figure that is kept is the one the engine computed rather than the one somebody typed.", "Only the audit trail, since the two figures can be rebuilt from the cost items and the activity dates whenever they are wanted again.", "The information: the disagreement is the finding, and the 63 days between 870 and 933 is the most useful number in EGINA''s schedule precisely because nobody planned it.", "The completeness score, since a plan that drops a section falls below 100 percent and stops being sanctionable at the screening tier."]'::jsonb, 2, 'Three questions turn a set of outputs into a plan that has been read: which number is this, what was it measured against, and does another number in the same plan answer the same question.'),
  ('fdp', 'advanced', 'final', null, 1, 'The scenario card colours a rate of 15 percent or more green, and the sweep ranks the plan''s drivers Oil Price, Production, CAPEX, OPEX. A reviewer reads a green 29.5998 percent beside the widest bar and calls the case risked. What has that reading assumed?', '["Nothing that is not already stated, since the colour applies the only hurdle rate in the studio and the widest swing of 3092.0051 names the driver most likely to move against the case.", "Only that the base is sound, since a green rate and a driver ranking are both properties of a case whose value of 2047.5653 million USD was struck on a capex of 2250.0000 the plan has reconciled.", "Two things neither output claims: a colour on a card is not a decision rule and carries no money beside it, and a ranking by swing is arithmetic leverage with nothing in it about how likely a 30 percent move is.", "That the tie-back was screened on the same terms, since 40.4321 percent is green as well and its own swing would have to be ranked before either concept could be called risked."]'::jsonb, 2, 'The green at 29.5998 percent says nothing about the 2047.5653 million USD standing beside it, and the sweep ranks by leverage as a work list for tightening an estimate rather than by likelihood.'),
  ('fdp', 'advanced', 'final', null, 2, 'At 70.0000 USD a barrel the subsea tie-back returns 40.4321 percent on a capex of 730.0000 and the FPSO returns 29.5998 percent on 2250.0000, while the tie-back is worth 1048.6281 million USD and the FPSO 2047.5653. Which reading is sound?', '["Both measures are true at once, since value per million of capex is 1.436477 for the tie-back and 0.910029 for the FPSO while the FPSO still returns the larger amount of money.", "The tie-back is the better development, because it wins on the rate and on payback at 3.2035 years against 3.8273, and two measures out of three settle a screening ranking.", "The FPSO is the better development, because a rate taken on 730.0000 of capex cannot be set against a rate taken on 2250.0000 until both have been restated on one capex.", "Neither ranking holds, because the two scenarios were struck at different discount rates and only values taken at a single rate of 10.0000 percent may be compared."]'::jsonb, 0, 'The rate says how hard the money worked and the NPV says how much came back. A portfolio sorted on 40.4321 percent hands the reader 1048.6281 in place of 2047.5653.'),
  ('fdp', 'advanced', 'final', null, 3, 'A reviewer divides the FPSO''s NPV of 2047.5653 million USD by the facility screening estimate of 1363.3524 and sets the result beside the tie-back''s value per million of capex of 1.436477. What is wrong with that pair?', '["Nothing, since a screening estimate and a concept capex are both class 5 figures in million USD and the two ratios are therefore struck on one footing.", "The FPSO''s value should have been the plan''s own cost items NPV rather than the scenario NPV, because only the cost items reach the 2250.0000 a facility estimate belongs beside.", "The tie-back''s ratio should have been re-struck on its own facility screening estimate of 184.6717, which is the figure that puts the two concepts on the same basis.", "The tie-back figure is taken on its concept''s whole capex of 730.0000, while 1363.3524 prices one facility and leaves out drilling of 520.0000 and subsea of 380.0000, so the FPSO''s like for like figure is 0.910029 on 2250.0000."]'::jsonb, 3, 'A value per million is only as good as the capex underneath it. The screening estimate belongs beside the concept''s facilities field of 1350.0000, a gap of 13.3524, and never beside a development that also drills wells and lays subsea.'),
  ('fdp', 'advanced', 'final', null, 4, 'A screening pack shows a payback equal to the concept life of 20.0000 years. What should a reader check before quoting it?', '["Whether the cumulative was discounted at 10.0000 percent before the crossing was read, because an undiscounted payback always lands later than a discounted one does.", "Whether the project paid back in its final year or never paid back at all, since one published case with zero production records payback as the project life by convention.", "Whether the price deck covered every producing row, because a deck that stops short leaves the later years unpriced and pushes the crossing into the final row.", "Whether the figure came from the concept schedule rather than the cash flow, because a FPSO sanctioned 2027-04-01 reaches first oil 2030-04-01, which is 36 months."]'::jsonb, 1, 'EGINA at 18.0000 and at 30.0000 USD a barrel both report never rather than a number. A payback equal to the life is the one figure that can be the honest answer or a substitution.'),
  ('fdp', 'advanced', 'final', null, 5, 'Run the EGINA scenarios past a screening threshold of 15 percent on the rate and the Low price case at 14.4152 percent fails. What has just been rejected?', '["A case the engine had already priced as worthless, since a rate below the threshold means the discounted flow at 48.0000 USD a barrel does not cover its own capex.", "Nothing at all, because a threshold of 15 percent and a discount rate of 10.0000 percent are the same test applied twice and the value had already failed the first of them.", "427.9436 million USD of value at a discount rate of 10.0000 percent, correctly by the rule''s own terms, with nothing on the card to show what the rejection cost.", "The weakest of the three FPSO cases, which the sweep had already found at its minus 30 percent oil price end of 501.5628 million USD on the plan''s own base."]'::jsonb, 2, '14.4152 is less than 15, so the verdict is right and uninformative. The rejected case is worth 427.9436 and a reader who sees only the verdict cannot tell it from a worthless one.'),
  ('fdp', 'advanced', 'final', null, 6, 'At 40.0000 USD a barrel the FPSO concept reports a rate of 8.2444 percent and an NPV of -161.0098 million USD. How do those two live together?', '["The flow earns 8.2444 percent and the screening case charges 10.0000 percent for money, so a real positive root still leaves the value below zero.", "The two cannot both stand, so the rate of 8.2444 percent is a clamped figure and not a root.", "The root was found above the band the engine searches and reported anyway, which is the reading the status above-clamp exists to warn a reader about.", "The rate was struck before royalty and tax and the value after both, so they differ."]'::jsonb, 0, 'The sign of the rate is not the test. The test is the rate against the rate money costs, and the NPV of -161.0098 has already made that comparison.'),
  ('fdp', 'advanced', 'final', null, 7, 'A published case with zero capex is worth 717.9604 and carries no internal rate of return whatsoever. What does that absence say?', '["The flow has two crossings rather than none, which is why the engine withholds a rate and records the status multiple-roots even on a case whose value is positive.", "The root sits above the upper edge of the band at 1000 percent, which is what a large receipt against a very small outlay gives, so the status reads above-clamp.", "The rate exists and is 0 by the engine''s convention, in the way the published case with zero production every year records 0 beside an NPV of -979.6325.", "Every year points the same way, so there is nothing to solve for."]'::jsonb, 3, 'The status is no-sign-change, and it is structural: a project that never asked for money up front has nothing for a return to be a return on. The 717.9604 is defined regardless.'),
  ('fdp', 'advanced', 'final', null, 8, 'Two published cases report above-clamp: one worth 133.3087 whose hidden root is 15389.6875 percent, and one worth 1074.4692 whose hidden root is 2305.7875 percent. What does that status assert?', '["That no root exists at all, which is what a flow whose years all carry one sign gives.", "That a root exists outside the band between -99 and 1000 percent, so the engine did not find it and will not print a number it never verified.", "That the root was found and then suppressed for being implausible, since a rate of four figures of percent would be read as a repeatable expectation on a card.", "That the flow crosses zero more than once, so each of the two recorded roots is genuine and neither of them has any claim to be the rate of return of the case."]'::jsonb, 1, 'A tiny outlay followed by a large single year explodes the ratio while the money stays small: 133.3087 of value against 15389.6875 percent. The status is a prompt to check the capex.'),
  ('fdp', 'advanced', 'final', null, 9, 'The published case whose price deck is shorter than its profile is worth 126.1636, reports multiple-roots, and has a recorded hidden root of -52.4425 percent. Why is -52.4425 not its rate of return?', '["A second root is equally valid, so the case has no single rate, and the unpriced years still carry their operating cost, which bends the flow back below zero.", "Because it lies below the floor of the search at -99 percent, and a root outside the band is never reported however carefully a golden has recorded it.", "Because the engine never reports a rate below zero, which is why the published case that never pays back carries the status ok and no number beside that status.", "Because the plan path refuses a short deck by name rather than pricing it, so no rate of any kind was ever computed for that flow to be able to carry."]'::jsonb, 0, 'Missing prices read as 0 in that fixture. At 30.0000 USD a barrel EGINA reads multiple-roots too, on -898.3507, and picking one root is the reader''s preference wearing the engine''s authority.'),
  ('fdp', 'advanced', 'final', null, 10, 'Before the repair the studio printed 1000 percent, in green, against the EGINA concept at 18.0000 USD a barrel. What was that figure?', '["The true root of that flow, which sits above the band and is recorded in the goldens in the way 2305.7875 percent is recorded for another published case.", "The rate at which the stress case breaks even, computed correctly and then labelled wrongly.", "The upper edge of the band the search covers, returned from where the search stopped, so it is a property of the search rather than of the cash flow.", "A placeholder the card drew when the engine returned nothing, in the way an index with no denominator was drawn as a clean 1.00 and labelled under budget."]'::jsonb, 2, 'The tell is that the number was exactly the boundary. The repaired engine reports null with the status no-root there, and the NPV of -1797.2732 sat on the same card the whole time.'),
  ('fdp', 'advanced', 'final', null, 11, 'A case worth -1797.2732 million USD reports no rate of return at all with a status of no-root, and a sweep is drawn around it anyway. What does that chart carry?', '["Nothing at all, since a case with no verified root inside the band of -99 to 1000 percent cannot be re-run and the sweep has no base to move around.", "A rate at each of the eight ends, since every run solves its own flow and the status of no-root belongs to the base run alone.", "The same eight ends the Base case gives, since the sweep moves the drivers and a status is a property of the flow rather than of the driver being moved.", "Eight re-runs of the case in money and a ranking of the drivers by leverage, with nothing on it to say that a rate was withheld or why."]'::jsonb, 3, 'The sweep reports values, so it draws with equal confidence on a case the engine would refuse to hand a rate. The ranking of Oil Price, Production, CAPEX, OPEX is leverage and carries no status and no likelihood.'),
  ('fdp', 'advanced', 'final', null, 12, 'The plan path refuses a deck that does not cover the profile: "the price deck has no price for production year 3: enter a price for every year of the profile". A published golden runs a short deck anyway and reports 126.1636 with multiple-roots. What does the pair teach?', '["That the refusal is a screening convenience only, since the same deck priced through the golden path returns a usable 126.1636 and a hidden root of -52.4425 percent.", "That the refusal stops a padded case from being priced at all, and the golden shows what padding does, since unpriced years still carry cost and the flow gains a second change of sign.", "That the two paths disagree about one set of inputs, so a reader should take the refusal from the plan and the rate from the golden and report whichever is available.", "That a deck shorter than its profile is padded with the last price it carries, which holds the revenue flat through the unpriced years and leaves one crossing in the flow."]'::jsonb, 1, 'Missing prices read as 0 in the fixture, so the later years produce barrels at no revenue and still pay for lifting them. The plan path refuses by name instead of pricing that.'),
  ('fdp', 'advanced', 'final', null, 13, 'On the plan''s own case the sweep''s minus 30 percent oil price end is 501.5628 against a base of 2047.5653. What produced 501.5628?', '["A complete re-run of the case with that one input moved and every other held, which is why the two ends of a row are rarely the same distance from the base.", "The base value scaled down by 30 percent and then discounted again at 10.0000 percent, which is the arithmetic that makes a tornado chart cheap to draw.", "The Low price scenario at 48.0000 USD a barrel carried across into the sweep, which is why the sweep and the scenario table agree on the downside of this plan.", "The worst of the eight runs, taken once the price fall had been combined with the capex overrun end of 1403.9781 to give the case its full downside."]'::jsonb, 0, 'Every row runs royalty, tax, the discount and the shape again. The Low price scenario is a different number, 427.9436 at 48.0000 USD a barrel.'),
  ('fdp', 'advanced', 'final', null, 14, 'The oil price swing is 3092.0051 and the production swing is 2839.5965 on the same 30 percent move. What separates them?', '["Royalty at 12.5000 percent and tax at 30.0000 percent are taken on revenue, so a price move is taxed once while a volume move is taxed twice over the life of the case.", "The production driver moves the plateau and the decline as well as the volume, so more of its move lands in later years where the discount of 10.0000 percent bites.", "A variable operating cost of 5.0000 USD a barrel travels with the barrels, so extra volume brings its own cost and an extra dollar of price brings none.", "The price driver moves every producing row while the production driver leaves year 0 untouched, and year 0 is the row carrying the capex of 2250.0000."]'::jsonb, 2, 'Over the Base life the operating cost is 3049.6464 against revenue of 16095.0492. The published case with no royalty and no tax keeps price the wider driver on a base of 2738.0331.'),
  ('fdp', 'advanced', 'final', null, 15, 'The sweep''s CAPEX row runs from 2691.1526 at minus 30 percent to 1403.9781 at plus 30 percent. Which of the plan''s figures did it move by 30 percent either way?', '["The facility screening estimate of 1363.3524 million USD, since a sweep prices the facility from its type and its nameplate of 60000 bopd before it moves anything.", "The 2250.0000 million USD the case was run on, which is the concept''s drilling, facilities and subsea fields added and is also what the plan''s cost items total.", "The concept''s facilities field of 1350.0000 million USD, since the drilling of 520.0000 and the subsea of 380.0000 are committed and only a facilities figure is open to an overrun.", "The CAPEX total less the Decommissioning provision of 260.0000 million USD, since the screening case carries capex and operating cost only."]'::jsonb, 1, 'The two capex estimates agree at 2250.0000 because the plan was costed against its concept, and the sweep moves that one figure. The screening estimate of 1363.3524 is a third number and belongs beside 1350.0000.'),
  ('fdp', 'advanced', 'final', null, 16, 'CAPEX runs from 2691.1526 at minus 30 percent to 1403.9781 at plus 30 percent, a swing of 1287.1745, while OPEX swings 323.8828 on the same move. Why is the capex row so much the wider?', '["The capex base of 2250.0000 is larger than the 95.0000 a year, and the sweep moves each driver by an absolute amount.", "The capex row runs backwards, and a swing across a reversed row always reads wider.", "Operating cost is taken before royalty and tax, so the government absorbs most of its move, while the capex move falls whole on the investor and is not shared with anybody.", "The capex lands in year 0 where discounting touches it least, and operating cost is spread across the producing years where the later portions count for less."]'::jsonb, 3, 'The shares of base are 0.628637 for capex and 0.158179 for operating cost. Both rows still run high to low, because more money spent is less money kept.'),
  ('fdp', 'advanced', 'final', null, 17, 'May the sweep''s minus 30 percent oil price end of 501.5628 be labelled a P90 NPV?', '["No, because a P-label belongs to a reserves distribution one fluid at a time, and 501.5628 is a single conditional run rather than a point on any distribution.", "Yes, provided the label goes on the minus 30 percent ends of all four drivers together, since those four downside runs bracket the low case of the plan between them.", "Yes, because the sweep moves every driver by the same 30 percent, so the eight ends are equally likely and the lowest of them is the low outcome by construction.", "No, because the right label for a downside run is P10, which names the high case of a distribution and so the low case of any value that is built on it."]'::jsonb, 0, 'EGINA''s oil P50 is 130.0000 MMbbl and its gas P50 is 70.0000 Bcf, and those labels came from a distribution somebody built. The sweep carries no claim about likelihood.'),
  ('fdp', 'advanced', 'final', null, 18, 'The lowest figure anywhere in the sweep is 501.5628. Is that the worst the case can do?', '["Yes, since the widest single driver, at a swing of 3092.0051, already carries any combination of moves that could be made to the case and its four drivers at once.", "Yes, because 30 percent is the largest move the sweep may make on a driver.", "No, because one driver moves at a time, so a price fall arriving with a capex overrun is nowhere in the table and sits below every figure printed in it.", "No, because the capex overrun end of 1403.9781 is lower still than that figure."]'::jsonb, 2, 'On the published marginal case with 900.0000 of capex at 45.0000 the price downside is -225.0477 and the capex overrun end is -44.7315, and the case where both happen is absent.'),
  ('fdp', 'advanced', 'final', null, 19, 'ODUDU-2 at 2028-12-31 reports a schedule index of 0.821326 and a cost index of 1.027027. How does one project read late and cheap on the same date?', '["The cost index leads the schedule index by a reporting period, so a project that has slowed reads cheap first and reads late only once the spending has caught up with it.", "The two ratios share the earned value of 8360000 and divide it by different things, a planned value of 10178668 and an actual cost of 8140000.", "The cost index is taken against the budget at completion of 32000000, not to a date.", "The two disagree whenever a percent complete somebody typed has gone stale."]'::jsonb, 1, 'One earned value over two denominators gives one answer about time and one about money. A report quoting a single index has answered only one of the two questions.'),
  ('fdp', 'advanced', 'final', null, 20, 'Across five as-of dates ODUDU-2''s planned value runs 0, 3429703, 10178668, 19026406 and 32000000 while its earned value stays at 8360000. What changed in the work between 2028-06-30 and 2028-12-31?', '["Procurement opened its window on 2028-08-01 and earned part of its 8600000, and that is the movement the planned value column records between those two rows.", "The team fell behind by roughly the difference between 3429703 and 10178668, which is the fall in the schedule index from 2.437529 to 0.821326 read back into the work.", "Detailed design slipped from its 65.0000 percent to a lower reading, since a schedule index cannot fall while the percent complete on every task is being held.", "Nothing at all, since only the date the question was asked moved."]'::jsonb, 3, 'The plan''s own demand rose past the work. Earned value and actual cost are unmoved on all five rows, and the cost index reads 1.027027 on every one of them.'),
  ('fdp', 'advanced', 'final', null, 21, 'One costed task with a planned cost of 900000 and no dates is added to ODUDU-2, and the as-of date is then moved from 2028-12-31 to 2029-06-30. Which figures move?', '["The planned value, which still rises from 10178668 to 19026406 across the five dated tasks, and the schedule index along with it.", "The completion ratio, which falls away from 0.256839 as the later date carries more of the budget at completion of 32900000 into its denominator.", "None of them, since the schedule index is absent on both dates and the completion ratio holds at 0.256839, the date reaching only a planned value the engine cannot phase.", "The earned value of 8450000 and the actual cost, since both are measured to the as-of date and a later date finds more work done and more money spent."]'::jsonb, 2, 'The engine reports no planned value at all while a costed task carries no window: "1 costed task carries no planned dates, so planned value cannot be time-phased". The figures that survive never knew the calendar in the first place.'),
  ('fdp', 'advanced', 'final', null, 22, 'A single task 90.0000 percent done half way through its own window reports a schedule index of 1.795082 and a completion ratio of 0.900000. Why can only one of the two pass one?', '["Earned value can never exceed the budget at completion, while a planned value taken before the last window closes is smaller than that budget, leaving the index room above one.", "The schedule index is allowed above one only while a window is open, and the completion ratio is read after it closes, by which time the whole budget has been scheduled.", "The ratio divides by the planned value of the task and the index divides by that task''s budget, so it is the index that carries the smaller of the two denominators.", "The engine clips the ratio at one to keep a progress figure readable and reports the index raw, because an index above one is a finding a reader is meant to see."]'::jsonb, 0, 'A task cannot be more than 100.0000 percent done and the engine refuses anything higher. ODUDU-2 reads 2.437529 at 2028-06-30 against a completion ratio of 0.261250.'),
  ('fdp', 'advanced', 'final', null, 23, 'At 2031-01-01 ODUDU-2''s schedule index and its completion ratio both read 0.261250. What does that agreement mean?', '["The project has finished the quarter of the work it was ever going to finish, which is the reading a schedule index and a progress ratio share once the two converge.", "The two ratios are one measurement under two names once the last window closes, which is the reason the repair kept both of them printed on the same report.", "The earned value of 8360000 has caught up with the planned value, so the project stands on plan at that date and the cost index of 1.027027 confirms that it does.", "Every planned window has closed, so the planned value has reached 32000000 and the index can no longer say early."]'::jsonb, 3, 'On every earlier row they disagree, and at 2028-06-30 they disagree widely, 2.437529 against 0.261250. The meeting is the calendar running out rather than the work finishing.'),
  ('fdp', 'advanced', 'final', null, 24, 'An as-of date the engine cannot parse is refused: "asOf is not a valid date: last Friday". Why is there no fallback to the day the report is run?', '["Because the engine reaches no clock at all, so no date could be supplied except through the same field that has just failed to be read as a date.", "A quietly substituted date makes every index on the report unreproducible, and ODUDU-2 gives 10178668 and 0.821326 only because 2028-12-31 was supplied.", "Because the current day would put the planned value at the budget at completion of 32000000, which is the one denominator that makes a schedule index meaningless.", "Because a date-only string read as UTC midnight lands on the day before anywhere west of Greenwich, so any substituted date is wrong by a day for half its readers."]'::jsonb, 1, 'The as-of date is an input like the planned costs. A pack quoting 10178668 without quoting its date has published a number nobody can reproduce.'),
  ('fdp', 'advanced', 'final', null, 25, 'Before the repair a planned cost the parser could not read counted as zero. What did that do to a task list like ODUDU-2''s?', '["It took the unreadable figure out of the budget at completion while the task kept its name and its dates, and every number downstream carried on printing.", "It dropped the task from the list altogether, so the report showed four tasks and any reader holding it beside the plan would have seen at once that one was gone.", "It refused the whole calculation and returned no indexes, which is the behaviour the repair kept and then extended to a negative planned cost of -100.", "It set that task''s earned value to its whole budget, since a cost of zero cannot be part complete, which pushed the cost index up past 1.027027."]'::jsonb, 0, 'A Procurement figure of 8600000 read as zero leaves a completion ratio that looks fine on a task list missing money. The engine now names the task: "Rig move: planned cost is not a number: $1,200".'),
  ('fdp', 'advanced', 'final', null, 26, 'Add one costed task to ODUDU-2 with a planned cost of 900000 at 10.0000 percent complete and no dates on it, read at the same 2028-12-31. What does the engine report?', '["The schedule index of 0.821326 unchanged, since a task carrying no dates contributes nothing to the planned value and nothing to the earned value either.", "A schedule index above 0.821326, because the new task lifts the earned value to 8450000 while the planned value of 10178668 stays exactly where it was.", "No schedule index and the reason for it, while the budget at completion rises to 32900000, earned value to 8450000 and the completion ratio reads 0.256839.", "Nothing beyond a refusal message, because a costed task with no planned dates is rejected outright in the way a backwards window is rejected outright."]'::jsonb, 2, 'The message is "1 costed task carries no planned dates, so planned value cannot be time-phased". Earned value, actual cost, the budget at completion, the ratio and the cost index all survive.'),
  ('fdp', 'advanced', 'final', null, 27, 'A project with no costed task at all now reports no schedule index, no cost index and no percent complete. What appeared there before the repair?', '["A row of zeros, so a plan nobody had costed was filed beside one that had stalled.", "A clean index of 1.00 under a heading saying the project was under budget, and a percent complete that came back as the string NaN.", "The basis line without any numbers beside it, which is the repaired behaviour arriving early, and the heading stayed blank until a costed task was entered in the list.", "The completion ratio standing in for the schedule index, which is the substitution the repair removed, so a project with no costs read 0.261250 like any other project."]'::jsonb, 1, 'The basis the engine now states is "no costed task, so there is no planned value". A ratio of one on a project with no numbers in it was the most reassuring card on the page.'),
  ('fdp', 'advanced', 'final', null, 28, 'A reviewer meets a schedule index of 1.795082 and a proposal to type 150 into a percent complete, and treats both as numbers above one the engine ought to handle alike. What separates them?', '["Nothing: both are clipped, the index back to one and the progress back to 100.0000 percent, which is why a task ahead of its own window cannot show it on either figure.", "The index is a ratio and the progress a percentage, so 1.795082 is accepted as 179.5082 percent of the plan and the 150 refused only because it was typed into the wrong field.", "The index is refused as well on any task whose window is still open, since a schedule reading may pass one only after the last window has closed and the whole budget has been scheduled.", "The index is a verified reading against a planned value smaller than the budget, and the 150 is refused at the input because earned value may not pass the budget at completion."]'::jsonb, 3, 'A task 90.0000 percent done half way through its window reads 1.795082 against a completion ratio of 0.900000, and the old capped ratio could never make that reading; progress of 150 meets "Overdone: percent complete must be between 0 and 100, not 150".'),
  ('fdp', 'advanced', 'final', null, 29, 'One published case reports a cost index of 0.000000 against an actual cost of 20.0000, and an empty task list reports a cost index of none. Why are those different findings?', '["The first is a very small index rounded down and the second an index the engine declined to round, so both of them describe money spent against work that nobody budgeted.", "The first belongs to a project with costs and no progress and the second to one with progress and no costs.", "0.000000 says money went out and no budgeted work came back, and none says there was nothing to divide by, which is a gap to fill rather than a result.", "Both are absences, printed as 0.000000 where an actual cost exists and as none where it does not."]'::jsonb, 2, 'Arithmetic on a null is the mistake: a roll-up that treats every none as zero drags its average down with projects that were never costed in the first place.'),
  ('fdp', 'advanced', 'final', null, 30, 'Procurement stands at 30.0000 percent of 8600000 on a task where nothing has actually started. Which check catches it?', '["No check does, since the guard is a range check rather than a truth check, so a readable figure inside 0 to 100 passes and puts earned value into a report with no work behind it.", "The schedule index catches it, because a task earning ahead of its own window drives that index above one and 0.821326 would have read differently at the date.", "The cost index catches it, because Procurement has spent 2450000 against its earned value and progress typed ahead of the work shows up as an index above 1.027027.", "The basis line catches it, because the engine states what it did and would name Procurement among the tasks whose progress it could not reconcile with their spending."]'::jsonb, 0, 'Acceptance means the numbers were readable and in range. Earned value is only as good as the progress typed into it, and the refusals guard the arithmetic rather than the judgement.'),
  ('fdp', 'advanced', 'final', null, 31, 'EGINA carries a facility screening estimate of 1363.3524 million USD. Which figure does it belong beside?', '["The concept''s capex of 2250.0000, which is the plan''s estimate of what the development costs and so the only total a facility estimate can properly be tested against.", "The concept''s facilities field of 1350.0000, a gap of 13.3524, since the screening estimate covers one facility.", "The cost items CAPEX total of 2250.0000, because a screening estimate and a budget are both statements about money the plan intends to spend on the development.", "The FPSO hull and topsides line of 1180.0000, because the screening estimate prices a hull from its type and its nameplate of 60000 bopd and from nothing else."]'::jsonb, 1, 'Setting 1363.3524 against 2250.0000 compares one facility with a development that also drills 520.0000 of wells and lays 380.0000 of subsea.'),
  ('fdp', 'advanced', 'final', null, 32, 'A plan states its own duration three ways, 870 days from the network, 933 days across the dates typed on the activities and 36 months from the concept, and reports a payback of 3.8273 years. Which of the four is not a statement about the schedule?', '["The 933 days, which is only the window somebody typed into the activities and carries nothing about how long the work itself takes.", "The 36 months, which the concept dates from its own start of 2027-04-01 rather than measuring it from any activity the plan carries.", "The 870 days, which is the logic''s answer about the work and says nothing about the calendar the plan will actually be run against.", "The payback of 3.8273 years, read off the cumulative cash flow, which moves with the oil price while the other three do not."]'::jsonb, 3, 'All three durations describe the schedule by three mechanisms, which is why 870, 933 and 36 months stand together. The cumulative runs -2250.0000, -1454.1875, -658.3750 and then 137.4375, and at 18.0000 USD a barrel the same case never pays back.'),
  ('fdp', 'advanced', 'final', null, 33, 'The plan''s cost items carry a Decommissioning provision of 260.0000 typed as ABEX, and the engine reports a CAPEX total of 2250.0000 and an OPEX total of 95.0000 a year. Where is the 260.0000?', '["In neither total, because the screening case carries capex and operating cost only, so a line can be in the plan, correct, and absent from the number the plan reports.", "Inside the CAPEX total of 2250.0000, beside the drilling of 520.0000 and the subsea of 380.0000, because a provision is money committed ahead of first oil.", "Spread through the operating years inside the 95.0000 a year, which is how an abandonment provision is charged, and taken again in the facility figure of 204.5029.", "Inside the facility screening estimate of 1363.3524, which carries decommissioning at 0.150000 of the capex the facility holds, so the plan''s own line duplicates it."]'::jsonb, 0, 'The engine totals are CAPEX 2250.0000 and OPEX 95.0000. The screening estimate does carry its own decommissioning figure of 204.5029, a different number from a different method.'),
  ('fdp', 'advanced', 'final', null, 34, 'Two numbers in a plan disagree, so one of them is dropped and the plan reads clean. What has been lost?', '["Nothing, provided the figure kept is the one the engine produced rather than a derived one.", "The audit trail alone, because both figures are still held in the plan''s own sections and a reader can recover the difference from the cost items and the concept fields.", "The information, since the 63 days between 870 and 933 is the most useful number in EGINA''s schedule precisely because nobody planned it.", "The agreement of 0.0000 between the scenario NPV and the plan''s own NPV, which is the reconciliation the studio performs for itself and the deletion quietly undoes."]'::jsonb, 2, 'A difference of zero earned by reconciliation is a finding and one assumed in advance is nothing at all. The economics difference is 0.0000 only because the plan was costed against its concept.'),
  ('fdp', 'advanced', 'final', null, 35, 'A reader wants the rate of return that goes with the sweep''s minus 30 percent oil price end of 501.5628. Where is it?', '["In the scenario table at 14.4152 percent, since the Low price case at 48.0000 USD a barrel is that same downside read through a different card of the studio.", "In the price rows at 8.2444 percent, because the sweep takes the price down to about the level the 40.0000 USD a barrel row prices and that row carries its own rate.", "In the base at 29.5998 percent reduced in the proportion the driver moved, because a rate and a value both scale with the input the sweep has changed.", "Nowhere in the sweep, whose eight ends are amounts of money."]'::jsonb, 3, 'A rate would need its own run, and the engine reports one only when it verifies a root inside the band between -99 and 1000 percent. On some flows there is none to verify.'),
  ('fdp', 'advanced', 'final', null, 36, 'Which measure is defined for every one of the five EGINA scenarios, including the case at 18.0000 USD a barrel?', '["The internal rate of return, since the engine returns a status for every case and a status of no-root is itself the answer the search arrived at for that flow.", "The NPV, defined for every cash flow at every discount rate whether or not a root exists, and reading -1797.2732 on that case.", "The payback, since a case that does not pay back is recorded at the project life.", "The swing, since the sweep re-runs each scenario across its four drivers and the widest of them, 3092.0051, exists for any case the engine is able to price."]'::jsonb, 1, 'The rate is missing on the stress case and the payback there is never. A card that leads with a rate has nothing to print on the case that most needs reading.'),
  ('fdp', 'advanced', 'final', null, 37, 'A status pack shows ODUDU-2 at 2028-12-31 with a schedule index of 0.821326 beside a completion ratio of 0.261250, and asks which of the two is wrong.', '["Neither of them, because they answer different questions, one against a planned value that moves with the date and one against a budget at completion that never moves.", "The completion ratio, because a figure reading the same on every as-of date cannot be a measurement of a project already known to be behind its own plan.", "The schedule index, because the earned value of 8360000 is a figure taken to the date and dividing it by a time-phased denominator counts the same progress twice.", "Both of them, because two measures of one schedule differing by that much show an input error, and only a figure the engine states a basis for belongs in a pack."]'::jsonb, 0, 'Which number is this, and what was it measured against. The same habit puts the network''s 870 days beside the calendar''s 933 days without calling either of them wrong.'),
  ('fdp', 'advanced', 'final', null, 38, 'A pack sets ODUDU-2''s budget at completion of 32000000 beside EGINA''s capex of 2250.0000 million USD and reports the development as well within its budget. What went wrong?', '["The comparison reached for the concept capex where the cost items CAPEX total of 2250.0000 was the like for like figure, a budget at completion being itself a sum of budget lines.", "The budget at completion should have been the planned value of 10178668 at its as-of date.", "They are different models in different units, a project schedule in whole currency units and a development plan in million USD, and neither measures the other.", "The capex should have carried the ABEX line of 260.0000 before any comparison was made."]'::jsonb, 2, 'The completion ratio of 0.261250 is progress against 32000000 and says nothing about any development plan. Ask which number this is before asking whether it agrees with another.'),
  ('fdp', 'advanced', 'final', null, 39, 'A cost the parser could not read once counted as zero, and every index on the report still reconciled. Which habit would have caught it?', '["Watching the completion ratio, which rises when a cost drops out of the budget at completion and would have read above 0.261250 on the same earned value of 8360000.", "Asking whether another number in the plan answers the same question, and holding the reported budget at completion against the costed lines 2400000, 5200000, 8600000, 12500000 and 3300000.", "Watching the cost index, since an actual cost is untouched by an unreadable planned cost and the index of 1.027027 would have moved against a shrunken earned value.", "Watching the basis line, which states that the planned value was time-phased to the as-of date and would have named the task whose planned cost it could not read."]'::jsonb, 1, 'Those five planned costs add to 32000000, and a ratio that has quietly moved looks ordinary on its own. Correct arithmetic on the wrong inputs is the hardest error to find.'),
  ('fdp', 'advanced', 'final', null, 40, 'EGINA at 18.0000 USD a barrel reports no rate, a risk with no probability contributes 0.0000 to an exposure of 269.0000 million USD, and a project with no costed task reports no index. What do the three share?', '["Each is a zero the engine reports as a number, so a roll-up may average them alongside the measured figures beside them without distorting what the average says.", "Each is a case the engine refuses outright and declines to price, in the way a price deck that does not cover the whole production profile is refused by name.", "Each is a low reading rather than a missing one, so an unscored risk sits in the Low band and a case with no rate sits at the bottom of any ranking made on rate.", "Each is an absence reported with the reason for it rather than a default filling the space."]'::jsonb, 3, 'A clamp of 1000 percent and an invented index of one used to fill exactly these spaces. The unscored risk carries a cost impact of 400.0000 and the health is 58 with it and 58 without.'),
  ('fdp', 'advanced', 'final', null, 41, 'Three reports arrive: a scenario with no rate of return, a project whose schedule index is none because one costed task carries no dates, and a project with no planned value at all. What does a reader take to a decision from each?', '["The NPV of -1797.2732 and a payback of never, then the earned value, the actual cost and the completion ratio of 0.256839, and then nothing until a cost is entered.", "A rate of 1000 percent, an index of one and a percent complete of zero, each being what the engine returns once its own search or its own denominator runs out.", "The status alone in all three, since no-root, a planned value that cannot be phased and a task list with no costs are findings rather than measurements and carry no figures.", "The completion ratio in all three, since it needs neither a root nor a calendar and reads 0.261250 wherever a budget at completion has been built from the task list."]'::jsonb, 0, 'The basis lines say which measurement is gone and why: "1 costed task carries no planned dates, so planned value cannot be time-phased" and "no costed task, so there is no planned value".'),
  ('fdp', 'advanced', 'final', null, 42, 'A portfolio roll-up averages a rate column holding -36.6747 percent, and a schedule index column in which every none has been entered as zero. Which of the two averages is sound?', '["The index column, because a schedule index of 0.000000 is a real measurement of a project that has earned nothing at all, so zero is the value that a missing index properly takes.", "Neither, because the repaired engine withholds a negative rate as it withholds an index.", "The rate column, because -36.6747 percent is a measured root, while a none entered as zero turns projects nobody measured into projects that are failing.", "Both, provided the count of contributing projects is printed beside each average."]'::jsonb, 2, 'Treating every none as one hides them instead. A schedule index of 0.000000 against a planned value of 50.0000 is a measurement, and none means there was no plan to ask anything.');
